            elif r == 2 or c == 2:
                out[r][c] = 4
            elif c < 2:
                out[r][c] = 1

        # Recover the row's repeating sequence from its surviving colored cells.
        cells = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
        if not cells:
            continue

        best = None
        for period in range(2, 13):
            buckets = {}
            for c, v in cells:
                buckets.setdefault(c % period, []).append(v)
            score = sum(max(vals.count(v) for v in set(vals))
                        for vals in buckets.values())
            # Most consistent period, with shorter periods breaking ties.
            key = (score, -period)
            if best is None or key > best[0]:
                best = (key, period, {
                    k: max(set(vals), key=vals.count)
                    for k, vals in buckets.items()
                })

        _, period, pattern = best
        for c in range(3, w):
            if grid[r][c] == 0 and c % period in pattern:
                out[r][c] = pattern[c % period]

    return out
